# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: local OS helper CLI. `sync` applies the repo's machine setup (chezmoi source in
# .os/home/: dotfiles, packages, bashrc hook); `save` captures this machine's changes back into
# .os/ (offering new packages/web apps), then commits + pushes. `pwd-store` saves the 1Password
# master password in gnome-keyring (via `secret-tool`); `pwd-copy` copies it to the clipboard
# (wl-copy) and clears it after a timeout. No file is written; the keyring is per-machine.
#
# Example CLI Commands (`os` alias comes from .os/rc; new machine: run .os/install.sh first):
#   1. Pull + preview + apply setup:         os sync
#   2. Preview only:                         os sync --dry-run --no-pull
#   3. Save machine changes + commit/push:   os save
#   4. Preview what save would capture:      os save --dry-run
#   5. Store (hidden prompt, asked twice):   os pwd-store
#   6. Copy to clipboard (clears after 5s):  os pwd-copy
# ---------------------------------------------------------------------------


# TODO: review ruff S603/S607 (subprocess untrusted input / partial exe path), ignored
# for .os/ in pyproject.toml per-file-ignores; decide if we actually care
# (eg resolve absolute paths via shutil.which)


from __future__ import annotations

import os
import shutil
import subprocess
import tomllib
from pathlib import Path
from typing import Annotated

import tomlkit
import typer

app = typer.Typer(no_args_is_help=True)

REPO = Path(__file__).resolve().parent.parent
CHEZMOI_SOURCE = REPO / ".os" / "home"
CHEZMOI_CONFIG = Path.home() / ".config" / "chezmoi" / "chezmoi.toml"
PACKAGES_FILE = CHEZMOI_SOURCE / ".chezmoidata" / "packages.toml"
SAVE_IGNORE = REPO / ".os" / "save-ignore.toml"
OMARCHY_PATH = Path(os.environ.get("OMARCHY_PATH", Path.home() / ".local" / "share" / "omarchy"))
APPLICATIONS = Path.home() / ".local" / "share" / "applications"
HICOLOR_APPS = Path.home() / ".local" / "share" / "icons" / "hicolor" / "256x256" / "apps"

KEYRING_ATTRS = ["service", "delulu-os", "account", "1password-master-password"]
# Fixed on purpose (not a CLI option) so the password never lingers on the clipboard.
CLEAR_AFTER_SECONDS = 5


@app.command()
def sync(
    *,
    pull: Annotated[bool, typer.Option(help="git pull --ff-only the repo first.")] = True,
    dry_run: Annotated[bool, typer.Option("--dry-run", help="Show what would change; change nothing.")] = False,
    yes: Annotated[bool, typer.Option("--yes", "-y", help="Apply without the confirmation prompt.")] = False,
) -> None:
    """Apply this repo's machine setup (.os/home/ via chezmoi) to the current machine."""
    _ensure_chezmoi()
    if pull:
        subprocess.run(["git", "-C", str(REPO), "pull", "--ff-only"], check=True)
    if dry_run:
        subprocess.run(["chezmoi", "apply", "--dry-run", "--verbose"], check=True)
        return
    diff = subprocess.run(["chezmoi", "diff"], capture_output=True, text=True, check=True).stdout
    if not diff:
        typer.echo("Already in sync.")
        return
    typer.echo(diff)
    if not yes:
        typer.confirm("Apply these changes?", abort=True)
    subprocess.run(["chezmoi", "apply"], check=True)


@app.command()
def save(
    *,
    message: Annotated[str, typer.Option("--message", "-m", help="Commit message.")] = "os save: update machine config",
    push: Annotated[bool, typer.Option(help="git push after committing.")] = True,
    dry_run: Annotated[bool, typer.Option("--dry-run", help="Show what would be saved; change nothing.")] = False,
    yes: Annotated[bool, typer.Option("--yes", "-y", help="Commit without the confirmation prompt.")] = False,
) -> None:
    """Capture machine changes into .os/ (tracked files, new packages/web apps); commit, push.

    To track some other new file, run `chezmoi add <path>` first.
    """
    _ensure_chezmoi()
    if dry_run:
        subprocess.run(["chezmoi", "re-add", "--dry-run", "--verbose"], check=True)
        for name, kind in _new_packages():
            typer.echo(f"new {kind} package: {name}")
        for desktop in _new_webapps():
            typer.echo(f"new web app: {desktop.stem}")
        typer.echo(_out(["git", "-C", str(REPO), "status", "--short", "--", ".os"]))
        return

    # Managed files edited on this machine (chezmoi skips templates; edit those in .os/home/).
    subprocess.run(["chezmoi", "re-add"], check=True)
    for name, kind in _new_packages():
        choice = _ask(f"New {kind} package '{name}'")
        if choice == "a":
            _append_toml(PACKAGES_FILE, ["packages", kind], name)
        elif choice == "i":
            _append_toml(SAVE_IGNORE, ["packages"], name)
    for desktop in _new_webapps():
        choice = _ask(f"New web app '{desktop.stem}'")
        if choice == "a":
            _add_webapp(desktop)
        elif choice == "i":
            _append_toml(SAVE_IGNORE, ["webapps"], desktop.stem)

    status = _out(["git", "-C", str(REPO), "status", "--short", "--", ".os"])
    if not status:
        typer.echo("Nothing to save.")
        return
    typer.echo(status)
    if not yes:
        typer.confirm(f"Commit these .os/ changes{' and push' if push else ''}?", abort=True)
    git = ["git", "-C", str(REPO)]
    commit = [*git, "commit", "-m", message, "--", ".os"]
    subprocess.run([*git, "add", "--", ".os"], check=True)
    # Pre-commit hooks may auto-fix files (eg JSON formatting) and fail once; restage, retry.
    if subprocess.run(commit, check=False).returncode != 0:
        subprocess.run([*git, "add", "--", ".os"], check=True)
        subprocess.run(commit, check=True)
    if push:
        _push(git)


def _push(git: list[str]) -> None:
    """Push, but ask first if commits other than the save commit would go out too."""
    unpushed = _out([*git, "log", "--oneline", "@{u}..HEAD"]).splitlines()
    if len(unpushed) > 1:
        typer.echo("Other unpushed commits would be pushed too:\n" + "\n".join(unpushed[1:]))
        if not typer.confirm("Push all of them?", default=False):
            typer.echo("Saved locally; push later with `git push`.")
            return
    if subprocess.run([*git, "push"], check=False).returncode != 0:
        typer.echo("Push rejected (remote likely ahead); run `git pull --rebase`, then `git push`.", err=True)
        raise typer.Exit(1)


def _ensure_chezmoi() -> None:
    if shutil.which("chezmoi") is None:
        subprocess.run(["sudo", "pacman", "-S", "--needed", "--noconfirm", "chezmoi"], check=True)
    # Points ~/.config/chezmoi/chezmoi.toml at .os/home/ (see .os/home/.chezmoi.toml.tmpl).
    if not CHEZMOI_CONFIG.exists():
        subprocess.run(["chezmoi", "init", "--source", str(CHEZMOI_SOURCE)], check=True)


def _out(cmd: list[str]) -> str:
    return subprocess.run(cmd, capture_output=True, text=True, check=True).stdout.strip()


def _ask(prompt: str) -> str:
    while (choice := typer.prompt(f"{prompt}: [a]dd, [i]gnore forever, [s]kip", default="s")) not in ("a", "i", "s"):
        typer.echo("Enter a, i or s.")
    return choice


def _append_toml(path: Path, keys: list[str], value: str) -> None:
    doc = tomlkit.parse(path.read_text())
    table = doc
    for key in keys:
        table = table[key]
    table.add_line(value)
    path.write_text(tomlkit.dumps(doc))


def _new_packages() -> list[tuple[str, str]]:
    """Explicitly installed packages not from Omarchy, not in packages.toml, not ignored."""
    tracked = tomllib.loads(PACKAGES_FILE.read_text())["packages"]
    known = {*tracked["pacman"], *tracked["aur"], *tomllib.loads(SAVE_IGNORE.read_text())["packages"]}
    for packages_file in (OMARCHY_PATH / "install").glob("*.packages"):
        known |= {line.strip() for line in packages_file.read_text().splitlines()}
    aur = set(_out(["pacman", "-Qqm"]).split())
    explicit = _out(["pacman", "-Qqe"]).split()
    return [(name, "aur" if name in aur else "pacman") for name in explicit if name not in known]


def _new_webapps() -> list[Path]:
    """Omarchy web app launchers not managed by chezmoi and not ignored."""
    managed = set(_out(["chezmoi", "managed", "--include", "files", "--path-style", "absolute"]).splitlines())
    ignored = set(tomllib.loads(SAVE_IGNORE.read_text())["webapps"])
    return [
        desktop
        for desktop in sorted(APPLICATIONS.glob("*.desktop"))
        if str(desktop) not in managed
        and desktop.stem not in ignored
        and "omarchy-launch-webapp" in desktop.read_text()
    ]


def _add_webapp(desktop: Path) -> None:
    """chezmoi-add a web app launcher + its icon, templating out the home dir."""
    text = desktop.read_text()
    icon = next((line.removeprefix("Icon=") for line in text.splitlines() if line.startswith("Icon=")), "")
    icon_path = Path(icon) if icon.startswith("/") else HICOLOR_APPS / f"{icon}.png"
    targets = [desktop, icon_path] if icon and icon_path.exists() else [desktop]
    subprocess.run(["chezmoi", "add", *map(str, targets)], check=True)
    home = str(Path.home())
    if home in text:
        source = Path(_out(["chezmoi", "source-path", str(desktop)]))
        source.with_name(f"{source.name}.tmpl").write_text(text.replace(home, "{{ .chezmoi.homeDir }}"))
        source.unlink()


@app.command()
def pwd_store() -> None:
    """Save the 1Password master password in gnome-keyring (prompted, never an arg)."""
    password: str = typer.prompt("1Password master password", hide_input=True, confirmation_prompt=True)
    subprocess.run(
        ["secret-tool", "store", "--label=1Password master password", *KEYRING_ATTRS],
        input=password.encode(),
        check=True,
    )
    typer.echo("Stored in gnome-keyring.")


@app.command()
def pwd_copy() -> None:
    """Copy the stored 1Password master password to the clipboard."""
    result = subprocess.run(["secret-tool", "lookup", *KEYRING_ATTRS], capture_output=True, check=False)
    if result.returncode != 0 or not result.stdout:
        typer.echo("No password found in gnome-keyring; run `pwd-store` first.", err=True)
        raise typer.Exit(1)
    subprocess.run(["wl-copy", "--type", "text/plain"], input=result.stdout, check=True)
    # Detached so the clear still happens after this CLI exits.
    subprocess.Popen(
        ["sh", "-c", f"sleep {CLEAR_AFTER_SECONDS} && wl-copy --clear"],
        start_new_session=True,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    typer.echo(f"Copied to clipboard; clearing in {CLEAR_AFTER_SECONDS}s.")


if __name__ == "__main__":
    app()
